{
  "summary": "A tool that normalizes a given name by removing leading and trailing whitespace and converting it to lowercase, returning a dictionary with the normalized version of the input name.",
  "functionalities": [
    "Normalizes input names by stripping whitespace from both ends and converting the string to lowercase.",
    "Returns a structured response containing only the normalized name in a dictionary format.",
    "Supports integration within a toolchain via a defined function interface for processing string inputs."
  ],
  "input_schema": {
    "$schema": "https://json-schema.org/draft/2024-10-31/schema",
    "properties": {
      "name": {
        "type": "string",
        "description": "The input string to be normalized by removing leading and trailing whitespace and converting to lowercase."
      }
    },
    "required": [
      "name"
    ],
    "type": "object"
  }
}
